(r, big) => {
    const cnt = big ? 100 : r.int(3, 6), m = big ? 20 : r.int(2, 4);
    const make = (base) => {
      const lo = Math.min(...base), hi = Math.max(...base);
      const k = r.int(-lo, 25 - hi);
      return base.map(c => String.fromCharCode(97 + c + k)).join("");
    };
    const base = Array.from({ length: m }, () => r.int(0, big ? 8 : 4));
    const odd = base.slice();
    const pos = r.int(0, m - 1);
    odd[pos] = (odd[pos] + r.int(1, 4)) % 6;
    // the odd word must really have a different pattern
    const gaps = (w) => w.slice(1).map((c, i) => c - w[i]).join(",");
    if (gaps(odd) === gaps(base)) odd[pos] = base[pos] + 7;
    const words = [];
    for (let i = 0; i < cnt - 1; i++) words.push(make(base));
    words.splice(r.int(0, cnt - 1), 0, make(odd));
    return [words];
  }

