function oddPatternWord(words: string[]): string {
  const key = (w: string) => {
    const gaps: number[] = [];
    for (let j = 0; j + 1 < w.length; j++) gaps.push(w.charCodeAt(j + 1) - w.charCodeAt(j));
    return gaps.join(",");
  };
  const keys = words.map(key);
  const count = new Map<string, number>();
  for (const k of keys) count.set(k, (count.get(k) ?? 0) + 1);
  return words[keys.findIndex(k => count.get(k) === 1)];
}

