class Solution:
    def oddPatternWord(self, words: List[str]) -> str:
        def key(w):
            return tuple(ord(w[j + 1]) - ord(w[j]) for j in range(len(w) - 1))
        keys = [key(w) for w in words]
        count = Counter(keys)
        for w, k in zip(words, keys):
            if count[k] == 1:
                return w
        return ""

