function oddPatternWord(words: string[]): string {
  const key = (w: string) => {
    let s = "";
    for (let j = 0; j + 1 < w.length; j++) s += (w.charCodeAt(j + 1) - w.charCodeAt(j)) + ",";
    return s;
  };
  const [a, b, c] = [key(words[0]), key(words[1]), key(words[2])];
  const common = a === b || a === c ? a : b; // if a matches neither, b and c are the pair
  for (const w of words) if (key(w) !== common) return w;
  return "";
}

